const N: number = parseInt(readline());
for (let i = 0; i < N; i++) {
    var inputs: string[] = readline().split(' ');
    const name: string = inputs[0];
    const price1: number = parseFloat(inputs[1]);
    const price2: number = parseFloat(inputs[2]);
    const price3: number = parseFloat(inputs[3]);

    const pricePerSquareCM1 = price1 / (11*11*Math.PI);
    const pricePerSquareCM2 = price2 / (13*13*Math.PI);
    const pricePerSquareCM3 = price3 / (16*16*Math.PI);

    if (pricePerSquareCM1 < pricePerSquareCM2 && pricePerSquareCM1 < pricePerSquareCM3)
        console.log(name + " 22cm");
    else if (pricePerSquareCM2 < pricePerSquareCM1 && pricePerSquareCM2 < pricePerSquareCM3)
        console.log(name + " 26cm");
    else
        console.log(name + " 32cm");
}
